    if (updates.length === 0) {
      const contratoActual = await pool.query(
        "SELECT * FROM contratos WHERE id = $1",
        [contratoId]
      );
      return res.json(contratoActual.rows[0]);
    }

    // Agregar el ID del contrato al final
    values.push(contratoId);
    const result = await pool.query(
      `UPDATE contratos 
       SET ${updates.join(", ")}
       WHERE id = $${paramIndex}
       RETURNING *`,
      values
    );

